const offer = ;

// Mapear campos para o contrato interno
const normalized = {
  schemaVersion: '1.0',
  source: offer.source,
  sourceOfferId: offer.externalId,
  sourceProductId: offer.productId,
  merchantId: offer.merchantId,
  merchantName: offer.merchantName,
  title: offer.title,
  brand: offer.brand,
  model: offer.model,
  identifiers: {
    gtin: offer.gtin,
    ean: offer.ean,
    isbn: offer.isbn,
    mpn: offer.mpn,
    asin: offer.asin,
  },
  categoryPath: offer.categoryPath,
  condition: offer.condition || 'new',
  price: {
    currentCents: Math.round(offer.price * 100),
    originalCents: offer.originalPrice ? Math.round(offer.originalPrice * 100) : null,
    currency: offer.currency || 'BRL',
    discountPercent: offer.discountPercent,
    installments: offer.installments,
    installmentValueCents: offer.installmentValue ? Math.round(offer.installmentValue * 100) : null,
  },
  shipping: {
    amountCents: offer.shippingCost ? Math.round(offer.shippingCost * 100) : null,
    isFree: offer.shippingCost === 0,
    confirmed: false,
  },
  tax: {
    amountCents: null,
    included: null,
    confirmed: false,
  },
  coupon: {
    code: offer.couponCode,
    description: offer.couponDescription,
    autoApplied: false,
  },
  availability: {
    inStock: offer.availability === 'in_stock',
    quantity: offer.quantity,
  },
  urls: {
    canonical: offer.canonicalUrl,
    affiliate: offer.affiliateUrl,
    image: offer.imageUrl,
  },
  seller: {
    name: offer.sellerName,
    id: offer.sellerId,
  },
  validity: {
    fetchedAt: new Date().toISOString(),
    lastVerifiedAt: new Date().toISOString(),
  },
  tracking: {
    campaign: 'telegram_freguesia',
    clickReference: offer-,
    attributionVerified: false,
  },
  rawHash: '', // Será preenchido depois
};

 = normalized;
